// items coming from "Get a row"
return items.map(item => {
  const row = item.json || {};

  return {
    json: {
      ...row,
      rowExists: !!row.user_id
    }
  };
});

// ONE combined Code node:
// - Timeframe-driven only (no speed logic)
// - Rounds timeframe + outputs to 1 decimal where relevant
// - FIX: includes `constraints` in the final output (and in notes as fallback)

function round1(n) {
  return Math.round(n * 10) / 10;
}

function calcMacros(input) {
  const required = [
    'height_cm',
    'weight_kg',
    'goal_weight_kg',
    'dob',
    'gender',
    'goal',
  ];

  for (const key of required) {
    if (input[key] === undefined || input[key] === null || input[key] === '') {
      return { error: `missing field: ${key}` };
    }
  }

  const {
    user_id,
    email = null,
    unit_system = 'metric',
    height_cm,
    weight_kg,
    goal_weight_kg,
    dob,
    gender,
    goal,
    constraints,
    duration_weeks,
    duration_months,
    max_safe_weekly_change_kg,
  } = input;

  // ✅ FIX: support both `constraints` and legacy `constraint`
  const rawConstraints = constraints ?? input.constraint;
  const normalizedConstraints =
    rawConstraints && String(rawConstraints).trim()
      ? String(rawConstraints).trim()
      : null;

  const H = Number(height_cm);
  const CW = Number(weight_kg);
  const TW = Number(goal_weight_kg);

  // ---------------------------
  // AGE
  // ---------------------------
  const [y, m, d] = String(dob).split('-').map(Number);
  const birth = new Date(y, (m || 1) - 1, d || 1);
  const today = new Date();

  let age_years = today.getFullYear() - birth.getFullYear();
  const hadBirthday =
    today.getMonth() > birth.getMonth() ||
    (today.getMonth() === birth.getMonth() &&
      today.getDate() >= birth.getDate());
  if (!hadBirthday) age_years--;

  // ---------------------------
  // BMR
  // ---------------------------
  const A = age_years;
  const BMR_male = 10 * CW + 6.25 * H - 5 * A + 5;
  const BMR_female = 10 * CW + 6.25 * H - 5 * A - 161;

  let BMR_raw;
  if (gender === 'male') BMR_raw = BMR_male;
  else if (gender === 'female') BMR_raw = BMR_female;
  else BMR_raw = (BMR_male + BMR_female) / 2;

  const bmr_kcal = Math.round(BMR_raw);

  // ---------------------------
  // TDEE
  // ---------------------------
  const tdee_kcal = Math.round(bmr_kcal * 1.45);

  // ---------------------------
  // GOAL VALIDATION
  // ---------------------------
  const deltaKg = TW - CW;

  if (goal === 'lose' && deltaKg >= 0)
    return { error: 'goal is lose but goal_weight_kg >= weight_kg' };

  if (goal === 'gain' && deltaKg <= 0)
    return { error: 'goal is gain but goal_weight_kg <= weight_kg' };

  const isMaintain = goal === 'maintain' || Math.abs(deltaKg) < 0.1;

  // ---------------------------
  // TIMEFRAME
  // ---------------------------
  let plan_weeks = Number(duration_weeks);

  if (!Number.isFinite(plan_weeks) || plan_weeks <= 0) {
    const months = Number(duration_months);
    if (Number.isFinite(months) && months > 0) {
      plan_weeks = months * 4.345;
    }
  }

  if (!isMaintain && (!Number.isFinite(plan_weeks) || plan_weeks <= 0)) {
    return { error: 'duration_weeks (or duration_months) is required' };
  }

  // ---------------------------
  // WEEKLY CHANGE
  // ---------------------------
  const kcal_per_kg = 7700;
  const safeWeekly =
    Number.isFinite(Number(max_safe_weekly_change_kg)) &&
    Number(max_safe_weekly_change_kg) > 0
      ? Number(max_safe_weekly_change_kg)
      : 0.5;

  let required_weekly_change_kg = 0;
  let used_weekly_change_kg = 0;

  if (!isMaintain) {
    required_weekly_change_kg = deltaKg / plan_weeks;
    const sign = required_weekly_change_kg >= 0 ? 1 : -1;
    used_weekly_change_kg =
      Math.min(Math.abs(required_weekly_change_kg), safeWeekly) * sign;
  }

  // ---------------------------
  // DAILY KCAL CHANGE
  // ---------------------------
  let daily_kcal_change = 0;
  if (!isMaintain) {
    daily_kcal_change = (used_weekly_change_kg * kcal_per_kg) / 7;
  }

  const MAX_DEFICIT = 750;
  const MAX_SURPLUS = 600;

  if (goal === 'lose' && daily_kcal_change < -MAX_DEFICIT)
    daily_kcal_change = -MAX_DEFICIT;
  if (goal === 'gain' && daily_kcal_change > MAX_SURPLUS)
    daily_kcal_change = MAX_SURPLUS;

  const daily_kcal_change_kcal = Math.round(daily_kcal_change);

  // ---------------------------
  // CALORIE TARGET
  // ---------------------------
  let calorie_target_kcal = Math.round(tdee_kcal + daily_kcal_change);

  const minKcal = Math.max(1200, Math.round(tdee_kcal * 0.7));
  if (calorie_target_kcal < minKcal) calorie_target_kcal = minKcal;

  // ---------------------------
  // MACROS
  // ---------------------------
  let protein_raw;
  if (goal === 'lose') protein_raw = 2.0 * CW;
  else if (goal === 'maintain') protein_raw = 1.7 * CW;
  else protein_raw = 1.8 * CW;

  const protein_target_g = Math.round(protein_raw);
  const protein_cal = protein_target_g * 4;

  const fat_floor_kcal = 0.8 * CW * 9;
  const fat_percent_kcal = 0.25 * calorie_target_kcal;
  const fat_target_g = Math.round(
    Math.max(fat_floor_kcal, fat_percent_kcal) / 9
  );

  const carb_target_g = Math.round(
    (calorie_target_kcal - (protein_cal + fat_target_g * 9)) / 4
  );

  if (carb_target_g < 0) return { error: 'negative carbs; check inputs' };

  // ---------------------------
  // BMI
  // ---------------------------
  const bmi = round1(CW / (H / 100) ** 2);

  // ---------------------------
  // TIME TO GOAL
  // ---------------------------
  const time_to_goal_weeks = isMaintain
    ? 0
    : Math.abs(deltaKg / used_weekly_change_kg);

  const time_to_goal_days = Math.round(time_to_goal_weeks * 7);
  const time_to_goal_months = round1(time_to_goal_weeks / 4.345);

  // ---------------------------
  // NOTES
  // ---------------------------
  const baseNotes = isMaintain
    ? `Your daily calorie target is ${calorie_target_kcal} kcal for maintenance.`
    : `Your daily calorie target is ${calorie_target_kcal} kcal based on your timeframe (${round1(
        plan_weeks
      )} weeks). Required weekly change: ${round1(
        required_weekly_change_kg
      )} kg/week. Used weekly change: ${round1(
        used_weekly_change_kg
      )} kg/week. Daily change: ${daily_kcal_change_kcal} kcal/day. Estimated time to goal: ${round1(
        time_to_goal_months
      )} months.`;

  const notes =
    baseNotes +
    (normalizedConstraints ? ` Constraints: ${normalizedConstraints}.` : '');

  return {
    user_id,
    email,
    unit_system,
    height_cm: H,
    weight_kg: CW,
    goal_weight_kg: TW,
    age_years,
    gender,
    goal,

    // ✅ constraints now always present if provided
    constraints: normalizedConstraints,

    bmi,
    bmr_kcal,
    tdee_kcal,

    duration_weeks: Number.isFinite(Number(duration_weeks))
      ? round1(Number(duration_weeks))
      : null,
    duration_months: Number.isFinite(Number(duration_months))
      ? round1(Number(duration_months))
      : null,
    plan_weeks_used: isMaintain ? null : round1(plan_weeks),

    required_weekly_change_kg: round1(required_weekly_change_kg),
    max_safe_weekly_change_kg: round1(safeWeekly),
    used_weekly_change_kg: round1(used_weekly_change_kg),

    daily_kcal_change_kcal,

    calorie_target_kcal,
    protein_target_g,
    carb_target_g,
    fat_target_g,

    time_to_goal_days,
    time_to_goal_weeks: round1(time_to_goal_weeks),
    time_to_goal_months,

    notes,
  };
}

// FINAL n8n RETURN
return items.map((item) => {
  const input = item.json.body ?? item.json;
  return { json: calcMacros(input) };
});

