=Generate a full Day-1 meal plan in valid JSON using the input below.

INPUT:
{{ JSON.stringify($json) }}

parameters.jsCode:
// items = output from "Meal Plan" node
const newItems = [];

for (const item of items) {
  // 1) Get AI output string from Meal Plan node
  const rawOutput = item.json.output;   // <-- from OpenAI Chat Model

  if (typeof rawOutput !== 'string') {
    throw new Error("Expected item.json.output to be a string but got: " + typeof rawOutput);
  }

  // 2) Parse the JSON string
  let plan;
  try {
    plan = JSON.parse(rawOutput);
  } catch (e) {
    throw new Error("Failed to parse Meal Plan JSON: " + e.message);
  }

  // 3) day_index from plan_type (e.g. "day_1" → 1)
  let dayIndex = 1;
  if (typeof plan.plan_type === 'string' && plan.plan_type.startsWith('day_')) {
    const n = parseInt(plan.plan_type.split('_')[1], 10);
    if (!Number.isNaN(n)) dayIndex = n;
  }

  // 4) Plan date = "today" in *local* server time, as YYYY-MM-DD
  const now = new Date();
  // convert to local-date string in YYYY-MM-DD (avoids UTC shift issues)
  const local = new Date(now.getTime() - now.getTimezoneOffset() * 60000);
  const planDate = local.toISOString().slice(0, 10);

  // 5) Day name (e.g. "Tuesday") from local date
  const dayName = local.toLocaleDateString('en-US', { weekday: 'long' }); // "Tuesday"

  // 6) Build output for the Supabase meal_plans table
  newItems.push({
    json: {
      // user_id will be taken from "Create a row" via expression in Supabase node
      plan_date: planDate,   // "2025-12-02"
      day_index: dayIndex,   // 1 (from plan_type)
      day_name: dayName,     // "Tuesday"
      meal_plan: plan,       // full JSON → jsonb column
    },
  });
}

return newItems;

